using Autonomous146;
using CoreSim;
using LineThrottle156;
using ThreeLap158;
using SharedWorldSpeedway;
using Xunit;
namespace CoreSim.Tests;
[Trait("Shard","core")]
public sealed class RobustThreeLap158Tests {
 [Fact]public void NewControllerRemainsExplicitlyOff(){var spec=StandingWorld144.Rider(StartingGate.B);Assert.Throws<InvalidOperationException>(()=>new Planner158(spec,false));}
 [Fact]public void PendingChangesActivationStateWithoutChangingObservedBody(){
  var spec=StandingWorld144.Rider(StartingGate.B);var initial=Program158.Initial(spec);var at=StandingWorld144.Frame().At(20,spec.OffsetMeters);var v=initial.Input.Rider with{Position=at.Position,Road=at.Road,Velocity=new(10,0),TotalReferenceMeters=20,DistanceMeters=20};
  var a=new State146(initial.Input with{Rider=v,Time=1,NextReview=1,Omega=10/.33,Active=new(0,.1f),Pending=new[]{new FreeRacingCommand(.8,1.04,new(.04f,0))}},initial.CrankOmega);
  var b=a with{Input=a.Input with{Pending=new[]{new FreeRacingCommand(.8,1.04,new(-.04f,1))}}};
  var rt=new Runtime158(spec,false,Hierarchical155.Program155.Options());var control=new Control158(rt,new(SpeedMetersPerSecond:10,CourseSeconds:1));var x=control.ActivationState(a);var y=control.ActivationState(b);
  Assert.Equal(a.Input.Rider,b.Input.Rider);Assert.NotEqual(x.Input.Rider.Velocity,y.Input.Rider.Velocity);Assert.NotEqual(x.Input.Rider.AngularVelocity,y.Input.Rider.AngularVelocity);Assert.Equal(1.24,x.Input.Time,9);Assert.Equal(1.24,y.Input.Time,9);Assert.Equal(1,a.Input.Time);Assert.Equal(1.04,a.Input.Pending[0].ActivationAt);
 }
 [Fact]public void LegalStandingInitialStateHasNoHiddenFutureCommands(){var s=Program158.Initial(StandingWorld144.Rider(StartingGate.B));Assert.Equal(0,s.Input.Rider.Speed);Assert.Empty(s.Input.Pending);Assert.Equal(new FreeRacingAction(0,0),s.Input.Active);var gap=new RacingLineGeometry(StandingWorld144.Frame()).Clearance(s.Input.Rider);Assert.True(Math.Min(gap.Inner,gap.Outer)>=.5);}
 [Fact]public void NoPublicMethodCanSeedAHistoryTape(){Assert.Null(typeof(Planner158).GetMethod("InitializeDiagnosticTape"));Assert.Null(typeof(Planner158).GetMethod("InitializeDiagnosticReview"));}
 [Fact]public void MemoizedJointInversePreservesOriginalActionBits(){var spec=StandingWorld144.Rider(StartingGate.B);var initial=Program158.Initial(spec);var reference=initial with{Input=initial.Input with{Time=1,NextReview=1,Omega=10/.33,Active=new(.01f,.1f),Rider=initial.Input.Rider with{Velocity=new(10,0),Drive=.1f}}};var state=reference with{Input=reference.Input with{Rider=reference.Input.Rider with{Heading=.001f,AngularVelocity=.002f,Velocity=new(10.02f,.001f)}}};var rt=new Runtime158(spec,false,Hierarchical155.Program155.Options());var control=new Control158(rt);var action=new FreeRacingAction(.01f,.1f);var original=Robust150.Joint150.Correct(rt.Alpha,state,reference,action,.05,.88);var memo=Joint158.Correct(rt.Alpha,state,reference,action,.05,.88,control);var repeated=Joint158.Correct(rt.Alpha,state,reference,action,.05,.88,control);Assert.Equal(BitConverter.SingleToInt32Bits(original.SteeringRadians),BitConverter.SingleToInt32Bits(memo.SteeringRadians));Assert.Equal(BitConverter.SingleToInt32Bits(original.Drive),BitConverter.SingleToInt32Bits(memo.Drive));Assert.Equal(memo,repeated);Assert.True(control.JointMemoHits>0);}
 [Fact]public void PrimedSearchCannotReplaceIndependentPhysics(){var spec=StandingWorld144.Rider(StartingGate.B);var state=Program158.Initial(spec);var rt=new Runtime158(spec,false,Hierarchical155.Program155.Options());rt.Begin(0);var c=new Control158(rt);c.ActivationState(state);Assert.True(rt.PrimedPrefixes>0);rt.Step(state,new(0,1));rt.CorruptSearchForDiagnostics();using var independent=rt.Operation("independent_preflight");Assert.Throws<InvalidOperationException>(()=>rt.Step(state,new(0,1)));}
 [Fact]public void LaunchLaneMergeIsSmoothAndDoesNotChangeNominalIntent(){var frame=StandingWorld144.Frame();var spec=StandingWorld144.Rider(StartingGate.B);var nominal=new Control158(new Runtime158(spec,false));var shifted=new Control158(new Runtime158(spec with{OffsetMeters=8.25f},false));Assert.Equal(8.25,shifted.TargetOffset(0),10);Assert.Equal(3.5,shifted.TargetOffset(frame.SegmentStartMeters(1)),10);for(int j=0;j<100;j++){var reference=j*2d;Assert.Equal(3.5,nominal.TargetOffset(reference),10);Assert.InRange(shifted.TargetOffset(reference),3.5,8.25);}}
 [Fact]public void TimeZeroAbstainHasNoInventedSweptInterval(){Assert.Null(Native158.MinimumSweep(Array.Empty<double?>()));Assert.Null(Native158.MinimumSweep(new double?[]{.8,null}));Assert.Equal(.6,Native158.MinimumSweep(new double?[]{.8,.6}));}
 [Fact]public void FinalSetHasTenDistinctConditionsAndSixIndependentCases(){var x=Study156.Read<System.Text.Json.JsonElement>(Study156.Root+"/docs/experiments/robust-three-lap/final-v6/scenarios-frozen.json");var rows=x.GetProperty("Scenarios").EnumerateArray().ToArray();Assert.Equal(10,rows.Length);Assert.Equal(10,rows.Select(r=>(r.GetProperty("Gate").GetString(),r.GetProperty("OffsetMeters").GetDouble())).Distinct().Count());Assert.Equal(6,rows.Count(r=>r.GetProperty("Role").GetString()=="independent"));Assert.Equal(5,rows.Count(r=>r.GetProperty("Held").GetBoolean()));}
 [Fact]public async Task ConcurrentBudgetsPreserveBothCompletedAttempts(){var directory=Path.Combine(Path.GetTempPath(),"study158-budget-"+Guid.NewGuid().ToString("N"));try{using var a=new Budget158("parallel-a",0,20,concurrent:true,evidenceDirectory:directory);using var b=new Budget158("parallel-b",0,20,concurrent:true,evidenceDirectory:directory);await Task.WhenAll(Task.Run(()=>a.Finish("a")),Task.Run(()=>b.Finish("b")));var rows=Study156.Read<System.Text.Json.JsonElement>(Path.Combine(directory,"budget.json")).EnumerateArray().ToArray();Assert.Equal(2,rows.Length);Assert.All(rows,r=>Assert.True(r.GetProperty("Complete").GetBoolean()));}finally{if(Directory.Exists(directory))Directory.Delete(directory,true);}}
 [Fact]public void FrozenScenariosAreDistinctStoppedAndPaired(){var x=Study156.Read<System.Text.Json.JsonElement>(Program158.Doc+"/scenarios-frozen.json");Assert.Equal(3,x.GetProperty("RequiredLaps").GetInt32());Assert.Equal(5,x.GetProperty("MinimumTrials").GetInt32());var s=x.GetProperty("Scenarios").EnumerateArray().ToArray();Assert.Equal(5,s.Length);Assert.Equal(5,s.Select(q=>q.GetProperty("OffsetMeters").GetDouble()).Distinct().Count());Assert.All(s,q=>{var spec=StandingWorld144.Rider(Enum.Parse<StartingGate>(q.GetProperty("Gate").GetString()!)) with{OffsetMeters=q.GetProperty("OffsetMeters").GetSingle()};var v=Program158.Initial(spec).Input.Rider;var gap=new RacingLineGeometry(StandingWorld144.Frame()).Clearance(v);Assert.Equal(0,v.Speed);Assert.True(Math.Min(gap.Inner,gap.Outer)>=.5);});}
}
